set -e
OUT="$PWD/out"; mkdir -p "$OUT/frames"
rm -rf "$PWD/proj_src"; mkdir -p "$PWD/proj_src"
echo '' | base64 -d | tar xz -C "$PWD/proj_src"
cd "$PWD/proj_src"
export DEBIAN_FRONTEND=noninteractive
sudo apt-get update -qq
sudo apt-get install -y -qq ffmpeg fonts-noto-cjk fonts-noto-cjk-extra >/dev/null 2>&1 || echo "[i] fonts step skipped"
npm init -y >/dev/null 2>&1
npm i puppeteer@23 --no-audit --no-fund --silent
node scripts/record.js spec.json "$OUT/frames"
ffmpeg -y -framerate 30 -i "$OUT/frames/f_%05d.jpg" -c:v libx264 -crf 19 -preset veryfast -pix_fmt yuv420p -movflags +faststart "$OUT/film.mp4"

rm -rf "$OUT/frames"
ls -lh "$OUT"
